const j = $input.first().json;
const body = j.body || j;
const guest = body.guest || {};
const dates = body.dates || {};
const pricing = body.pricing || {};
const payment = body.payment || {};
const booking_id = body.booking_id || body.bookingId || 'ASK-????';
const guest_name = guest.name || body.guest_name || '';
const phone = guest.phone || body.phone || '';
const email = guest.email || body.email || '';
const checkin = dates.checkin || body.checkin || '';
const checkout = dates.checkout || body.checkout || '';
const nights = dates.nights || body.nights || '';
const total = (pricing.total != null ? pricing.total : body.total) || '';
const status = (payment.status || body.status || 'Paid');
const wallet_token = body.wallet_token || '';
const wallet_url = body.wallet_url || ('https://booking.mavash.net/w/' + wallet_token);
const esc = (s) => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const telegramText = [
  '<b>הזמנה חדשה</b> - דירת אשקלון',
  'ID: ' + esc(booking_id),
  'אורח: ' + esc(guest_name) + ' | ' + esc(phone),
  'תאריכים: ' + esc(checkin) + ' עד ' + esc(checkout) + ' (' + esc(nights) + ' לילות)',
  'סהכ: ' + esc(total) + ' שח',
  'סטטוס: ' + esc(status),
  'מקור: ' + esc(body.source || 'direct_website'),
  wallet_url ? ('Wallet: ' + esc(wallet_url)) : '',
  '',
  '[אשר] [שלח קוד] [Wallet]'
].filter(Boolean).join('\n');
return [{ json: {
  booking_id, guest_name, phone, email, checkin, checkout, nights,
  guests_count: body.guests_count || 2, total, status,
  source: body.source || 'direct_website', wallet_token, wallet_url,
  payplus_trx: (payment.transaction_id || body.payplus_trx || ''),
  telegramText, supabase_id: body.supabase_id || null,
}}];
